  NSDictionary *stats=nil;NSError *error=nil;NSDate *start=NSDate.date;NSArray *out=[TFAIContextProjection project:history schemas:schemas statistics:&stats error:&error];double elapsed=-start.timeIntervalSinceNow;
  checks++;BOOL fits=out&&[stats[@"afterTextJSONBytes"] unsignedIntegerValue]<=cap;if(!fits)failures++;
  if(out){checks+=2;if(!Pairs(out)){NSLog(@"FAIL orphaned tool pair");return 1;}BOOL kept=NO;for(NSDictionary *m in out)if([m[@"content"] isEqual:user])kept=YES;if(!kept){NSLog(@"FAIL original user changed");return 1;}}
