 NSDictionary *report=@{@"kind":@"context_pressure_budget_matrix",@"cases":@(rows.count),@"avoidable_blocks":@(failures),@"originals_recoverable":@(recoverable),@"checks":@(checks),@"rows":rows};NSString *path=NSProcessInfo.processInfo.environment[@"DYLIX_PRESSURE_REPORT"];if(path)[J(report) writeToFile:path atomically:YES encoding:NSUTF8StringEncoding error:nil];printf("PRESSURE cases=%lu avoidableBlocks=%lu originalsRecoverable=%lu checks=%lu\n",rows.count,failures,recoverable,checks);
